package io.github.diodeme.ji.relay.protocol;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;
import org.junit.jupiter.api.Test;

final class RelayProtocolTest {
    @Test
    void currentAndPreviousHostProtocolsAreSupportedWithoutFallbackPath() {
        assertTrue(RelayProtocol.supportsHostProtocol(1));
        assertTrue(RelayProtocol.supportsHostProtocol(0));
        assertFalse(RelayProtocol.supportsHostProtocol(2));
    }

    @Test
    void routeAssociatedDataBindsDirectionCounterEpochAndAllRouteIdentities() {
        var route = new RelayProtocol.Route("tenant-1", "route-1", "host-1", "device-1");
        byte[] baseline = RelayProtocol.routeAssociatedData(
                route, RelayProtocol.Direction.CLIENT_TO_HOST, 7, 2);
        assertNotEquals(Arrays.toString(baseline), Arrays.toString(RelayProtocol.routeAssociatedData(
                route, RelayProtocol.Direction.HOST_TO_CLIENT, 7, 2)));
        assertNotEquals(Arrays.toString(baseline), Arrays.toString(RelayProtocol.routeAssociatedData(
                new RelayProtocol.Route("tenant-1", "route-2", "host-1", "device-1"),
                RelayProtocol.Direction.CLIENT_TO_HOST, 7, 2)));
        assertNotEquals(Arrays.toString(baseline), Arrays.toString(RelayProtocol.routeAssociatedData(
                route, RelayProtocol.Direction.CLIENT_TO_HOST, 8, 2)));
    }
}
